"use client";

import { useEffect, useState } from "react";
import EventRegistrationModal from "@/components/EventRegistrationModal";
import Link from "next/link";
import WaveHeader from "@/components/WaveHeader";

interface Event {
    id: string;
    title: string;
    description: string;
    startDate: string;
    endDate?: string;
    location: string;
    imageUrl?: string;
    eventType: string;
    isOpen: boolean;
}

const demoEvents: Event[] = [
    { id: "1", title: "Олон Улсын Зуслангийн Эрдэмтэн Судлаачдын 3-р Хурал", description: "Ази Номхон Далайн орнуудын болон бусад олон улсын судлаачид оролцох.", startDate: "2024-10-15T00:00:00Z", location: "Улаанбаатар хот", eventType: "CONFERENCE", isOpen: true },
    { id: "2", title: "Артек ОУХТ Солилцооны Хөтөлбөр 2024", description: "ОХУ-ын Артек зусланд амрах хүүхдүүдийн бүртгэл.", startDate: "2024-06-01T00:00:00Z", location: "ОХУ, Гурзуф", eventType: "EXCHANGE_PROGRAM", isOpen: true },
    { id: "3", title: "Зуслангийн Удирдлагын Нэгдсэн Сургалт", description: "Зуслангуудын удирдлага, менежерүүдэд зориулсан чадавхжуулах сургалт.", startDate: "2024-05-10T00:00:00Z", location: "Цонжин болдог", eventType: "TRAINING", isOpen: false },
];

export default function EventsPage() {
    const [events, setEvents] = useState<Event[]>([]);
    const [loading, setLoading] = useState(true);

    const [isModalOpen, setIsModalOpen] = useState(false);
    const [selectedEventId, setSelectedEventId] = useState("");
    const [selectedEventTitle, setSelectedEventTitle] = useState("");

    const openModal = (id: string, title: string) => {
        setSelectedEventId(id);
        setSelectedEventTitle(title);
        setIsModalOpen(true);
    };

    useEffect(() => {
        async function fetchEvents() {
            try {
                const response = await fetch("/api/events");
                const data = await response.json();
                if (Array.isArray(data)) {
                    setEvents(data.length > 0 ? data : demoEvents);
                }
            } catch (error) {
                console.error("Failed to load events", error);
                setEvents(demoEvents);
            } finally {
                setLoading(false);
            }
        }

        fetchEvents();
    }, []);

    const formatDateRange = (start: string, end?: string) => {
        const options: Intl.DateTimeFormatOptions = { year: 'numeric', month: '2-digit', day: '2-digit' };
        const startDateString = new Date(start).toLocaleDateString('mn-MN', options);
        if (end) {
            const endDateString = new Date(end).toLocaleDateString('mn-MN', options);
            if (startDateString !== endDateString) return `${startDateString} - ${endDateString}`;
        }
        return startDateString;
    };

    const getTypeLabel = (type: string) => {
        switch (type) {
            case 'CONFERENCE': return 'Хурал, зөвлөгөөн';
            case 'EXCHANGE_PROGRAM': return 'Солилцооны хөтөлбөр';
            case 'TRAINING': return 'Сургалт';
            default: return 'Бусад';
        }
    };

    return (
        <div className="min-h-screen bg-white font-sans pb-24 text-[#0F1B3D]">
            {/* Navy Header Banner */}
            <WaveHeader title="АРГА ХЭМЖЭЭ" subtitle="Олон улсын болон үндэсний хэмжээний арга хэмжээ, хурал, солилцооны хөтөлбөрийн мэдээлэл." />

            <div className="container mx-auto px-4 max-w-7xl relative z-20 pt-16">
                {loading ? (
                    <div className="flex justify-center py-20">
                        <div className="animate-spin rounded-full h-12 w-12 border-4 border-slate-200 border-t-[#0F1B3D]"></div>
                    </div>
                ) : events.length > 0 ? (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                        {events.map((event, i) => (
                            <EventCard 
                                key={event.id} 
                                event={event} 
                                formatDateRange={formatDateRange}
                                getTypeLabel={getTypeLabel}
                                openModal={openModal}
                                index={i}
                            />
                        ))}
                    </div>
                ) : (
                    <div className="text-center py-24 bg-white rounded-3xl border-2 border-dashed border-slate-200 shadow-sm max-w-2xl mx-auto mt-20">
                        <div className="text-7xl mb-6">📅</div>
                        <h3 className="text-2xl font-black text-[#0F1B3D] mb-3">Одоогоор зарлагдсан арга хэмжээ алга байна</h3>
                        <p className="text-slate-500 max-w-md mx-auto font-medium text-lg">Тун удахгүй шинэ арга хэмжээнүүд нэмэгдэх болно.</p>
                    </div>
                )}
            </div>

            {/* Registration Modal */}
            <EventRegistrationModal 
                isOpen={isModalOpen} 
                onClose={() => setIsModalOpen(false)} 
                eventId={selectedEventId}
                eventTitle={selectedEventTitle}
            />
        </div>
    );
}

function EventCard({ event, formatDateRange, getTypeLabel, openModal, index }: { 
    event: Event; 
    formatDateRange: (start: string, end?: string) => string; 
    getTypeLabel: (type: string) => string;
    openModal: (id: string, title: string) => void;
    index: number;
}) {
    return (
        <div className="group bg-white rounded-3xl border border-slate-100 shadow-[0_10px_40px_-15px_rgba(0,0,0,0.1)] flex flex-col overflow-hidden h-full transition-all duration-300 hover:shadow-2xl hover:-translate-y-2">
            {/* Image section */}
            <div className="aspect-[16/10] w-full relative overflow-hidden bg-slate-100 flex items-center justify-center shrink-0">
                {event.imageUrl ? (
                    <img src={event.imageUrl} alt={event.title} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105" />
                ) : (
                    <div className="text-6xl bg-slate-100 w-full h-full flex items-center justify-center grayscale opacity-30 group-hover:grayscale-0 group-hover:opacity-100 transition-all duration-500">🎟️</div>
                )}
                
                {/* Status Badge */}
                <div className="absolute top-4 right-4">
                    {event.isOpen ? (
                        <span className="bg-emerald-500 text-white text-[10px] font-bold uppercase px-3 py-1.5 rounded-full shadow-lg">
                            Нээлттэй
                        </span>
                    ) : (
                        <span className="bg-slate-400 text-white text-[10px] font-bold uppercase px-3 py-1.5 rounded-full">
                            Хаагдсан
                        </span>
                    )}
                </div>
            </div>

            <div className="p-6 flex flex-col flex-1">
                <div className="text-xs font-bold text-[#D4A843] uppercase tracking-widest mb-3">
                    {getTypeLabel(event.eventType)}
                </div>
                
                <h3 className="text-xl font-bold mb-3 line-clamp-2 leading-tight text-[#0F1B3D] group-hover:text-blue-600 transition-colors">
                    {event.title}
                </h3>
                
                <p className="text-sm font-medium text-slate-500 flex-grow mb-6 line-clamp-3">
                    {event.description}
                </p>
                
                <div className="space-y-3 shrink-0 bg-slate-50 rounded-xl p-4 mb-6">
                    <div className="flex items-center gap-3">
                        <div className="w-6 h-6 rounded-full bg-[#0F1B3D]/5 flex items-center justify-center text-[#0F1B3D]">
                            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                        </div>
                        <span className="font-bold text-xs text-slate-700">{formatDateRange(event.startDate, event.endDate)}</span>
                    </div>
                </div>
                
                <div className="mt-auto flex gap-3 shrink-0">
                    <button
                        disabled={!event.isOpen}
                        onClick={() => openModal(event.id, event.title)}
                        className="flex-1 inline-flex h-12 items-center justify-center rounded-full bg-[#0F1B3D] px-4 text-xs font-bold text-white transition-all hover:bg-[#1A2B5C] hover:shadow-lg disabled:opacity-30 disabled:pointer-events-none disabled:shadow-none"
                    >
                        Бүртгүүлэх
                    </button>
                    <Link href={`/events/${event.id}`} className="inline-flex h-12 w-12 items-center justify-center rounded-full border-2 border-slate-200 text-[#0F1B3D] hover:bg-slate-50 transition-colors">
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 5l7 7-7 7"/></svg>
                    </Link>
                </div>
            </div>
        </div>
    );
}
